'use strict';
const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto'),{spawnSync}=require('node:child_process');
const {unpack}=require('../../tools/restore-apk-analysis-20261101.cjs');
const fixture=path.resolve(__dirname,'../.work/package-audit-fixture'),tool=path.resolve(__dirname,'../../tools/package-apk-analysis-20261101.cjs');
fs.mkdirSync(path.join(fixture,'cas'),{recursive:true});
const sha=b=>crypto.createHash('sha256').update(b).digest('hex');
const data=[Buffer.alloc(0),Buffer.from('package audit'),Buffer.alloc(513,47)],objects=data.map(b=>({sha256:sha(b),bytes:b.length}));
for(let i=0;i<data.length;i++)fs.writeFileSync(path.join(fixture,'cas',objects[i].sha256),data[i]);
const save=objs=>fs.writeFileSync(path.join(fixture,'cas-index.json'),JSON.stringify({schemaVersion:1,objects:objs}));
const run=()=>spawnSync(process.execPath,[tool,'--analysis-root',fixture],{encoding:'utf8',windowsHide:true});
(async()=>{const results=[];save(objects);let r=run();results.push({name:'valid-indexed-pack',pass:r.status===0,error:r.stderr||null});if(r.status)throw Error(r.stderr);
 const manifest=JSON.parse(fs.readFileSync(path.join(fixture,'release-packs.json'))),first=manifest.packs.map(p=>p.sha256).join();
 r=run();const second=JSON.parse(fs.readFileSync(path.join(fixture,'release-packs.json'))).packs.map(p=>p.sha256).join();results.push({name:'deterministic-repeat',pass:r.status===0&&first===second,error:r.stderr||null});
 for(const p of manifest.packs)await unpack(path.join(fixture,'packs',p.name),p,path.join(fixture,'restored'));
 results.push({name:'pack-restore-roundtrip',pass:objects.every(o=>sha(fs.readFileSync(path.join(fixture,'restored/cas',o.sha256)))===o.sha256)});
 save([{...objects[1],bytes:999}]);r=run();results.push({name:'wrong-indexed-size-rejected',pass:r.status!==0,error:r.stderr.trim()});
 save([objects[1],objects[1]]);r=run();results.push({name:'duplicate-index-hash-rejected',pass:r.status!==0,error:r.stderr.trim()});
 save(objects);fs.writeFileSync(path.join(fixture,'cas',objects[1].sha256),Buffer.from('CORRUPTED'));r=run();results.push({name:'corrupted-object-rejected',pass:r.status!==0,error:r.stderr.trim()});
 const result={checkedAt:new Date().toISOString(),passed:results.filter(x=>x.pass).length,total:results.length,cases:results};fs.writeFileSync(path.join(__dirname,'package-fixture-results.json'),JSON.stringify(result,null,2)+'\n');console.log(JSON.stringify(result,null,2));if(results.some(x=>!x.pass))process.exitCode=1;
})().catch(e=>{console.error(e);process.exitCode=1});
